#!/usr/bin/env node
/**
 * بوّابةُ ميزانيّةِ الوثائق المحقونة — تجعل النموَّ الصامتَ مرئيّاً.
 * ─────────────────────────────────────────────────────────────────
 * لماذا وُجدت (مقيسٌ 2026-09-20 من تاريخ git، لا مُقدَّر):
 *
 *   2026-09-11  ⇒ 69,257 بايت
 *   2026-09-12  ⇒ 37,921   🟢 تقليمٌ كبير (−31,336) بنقل التفصيل إلى `_docs/`
 *   2026-09-20  ⇒ 57,119   🔴 +19,198 في ثمانية أيام (~+2,400/يوم)
 *
 * ⇒ **التقليمُ نُفِّذ فعلاً ثمّ أُعيد بناءُ ثلثيه في ثمانية أيام.** والعلّةُ ليست
 * الحجمَ ولا أن الإضافات غيرُ مبرَّرة — كلُّ جلسةٍ تضيف ~1,500 بايتاً **بحقّ**.
 * العلّةُ أن **المجموعَ غيرُ مرئيٍّ لأحد**.
 *
 * 🔴 ولماذا يهمّ الحجمُ أصلاً — وهو ليس تفضيلاً جمالياً:
 * `CLAUDE.md` يُحقَن في **كلّ** جلسةٍ على هذا المستودع، و**يُعاد إرسالُه مع كلّ
 * نداءٍ إلى النموذج** لا مرّةً واحدة. فكلُّ بايتٍ هنا يُدفع ثمنُه مئاتِ المرّات يومياً.
 *
 * ── مراجعةُ جلسة `SchoolApp-gas` ‏2026-09-20 — ثلاثةُ عيوبٍ أُصلحت هنا ──────────
 *
 * ① 🔴 **المقياسُ الصحيحُ المعدّلُ لا السقف.** السقفُ الضيّق (‏+881) يحمرّ عند **أوّل
 *    دفعةِ توثيقٍ مشروعة** ⇒ يُرفَع في كلّ دفعةٍ تقريباً ⇒ **تصير الخطوةُ طقساً
 *    يُمرَّر بلا قراءة، وهي أسوأُ من غيابها لأنها تُقرأ ضبطاً قائماً.**
 *    🟢 ⇒ الحارسُ الأوّلُ صار **سقفاً على الزيادة في الدفعة الواحدة** (`MAX_DELTA`):
 *    يمرّ على الدفعة المشروعة ويحمرّ على القفزة، **ولا يحتاج رفعاً دورياً أصلاً**.
 *    والسقفُ المطلق بقي **حاجزاً خلفيّاً بعيداً** لا بوّابةً يوميّة.
 *
 * ② 🔴 **بوّابةٌ ثمنُها زيادةٌ في الشيء الذي تحرسه.** كان بابُ «ارفع السقفَ واكتب لماذا»
 *    يُقرأ أمراً بكتابة التبرير **داخل الملفّ المحروس نفسِه**.
 *    🟢 ⇒ صار منصوصاً: **السببُ في وصف الـPR وتعليقِ هذا السكربت — لا في `CLAUDE.md`.**
 *
 * ③ 🔴 **حارسٌ سليمٌ بنطاقٍ أضيقَ من العلّة يُقرأ أوسعَ ممّا يقيس.** الأساسُ المحقونُ
 *    في الجلسة **أربعُ طبقاتٍ** وهذا المستودعُ يملك **واحدةً**: `~/.claude/CLAUDE.md`
 *    و`~/CLAUDE.md` خارجَه تماماً، وفهرسُ الذاكرة في `~/.claude/projects/…`.
 *    ⇒ أخضرُ هنا يعني «وثيقةُ هذا المستودع مضبوطة» **لا «الأساسُ مضبوط»**.
 *    🟢 ⇒ المخرَجُ يقول صراحةً ما لا يقيسه. **وحدُّ الحارس يُعلَن ولا يُترك للقارئ.**
 *
 * ⚠️ وحدٌّ رابعٌ يبقى قائماً: يقيس **البايتات لا التوكنات**. والعربيّةُ في UTF-8
 * بايتان للمحرف تقريباً ونسبةُ التوكن تختلف ⇒ الرقمُ **وكيلٌ مستقرٌّ للاتّجاه**
 * لا قياسٌ للتوكن. والقياسُ الحاكمُ `/context` — وهو أمرُ واجهةٍ يكتبه المالك.
 */

'use strict';

var fs = require('fs');
var path = require('path');
var cp = require('child_process');

var ROOT = path.join(__dirname, '..', '..');

/**
 * 🔴 `MAX_DELTA` هو الحارسُ العامل. ضُبط 2026-09-20 عند 3,000 — أي ضِعفَ متوسّطِ
 *    الدفعة المقيس (~1,500) ودون القفزة المرصودة (‏+11,107 في 2026-09-10).
 *    ⇒ يمرّ على التوثيق المعتاد ويحمرّ على الكتلة المنقولة.
 * 🔴 و`maxBytes` حاجزٌ خلفيٌّ بعيد: 69,257 = الحجمُ الذي استدعى تقليمَ 09-12.
 *    ⇒ معناه «لا نعود إلى حيث كنّا»، لا «لا تكتب اليوم».
 */
var BUDGET = [
  {
    file: 'CLAUDE.md',
    maxBytes: 69257,
    maxDelta: 3000,
    why: 'يُحقَن في كلّ جلسةٍ ويُعاد إرسالُه مع كلّ نداء'
  }
];

/** ما لا تقيسه هذه البوّابة — يُطبع دائماً، لا عند الفشل فقط. */
var NOT_COVERED = [
  '~/.claude/CLAUDE.md  و  ~/CLAUDE.md — يُحقنان في الجلسة وهما خارج هذا المستودع',
  '~/.claude/projects/…/memory/MEMORY.md — فهرسُ الذاكرة، يُحقَن كذلك',
  'التوكنات — هذا قياسُ بايتات؛ الحاكمُ `/context`'
];

function verdict(bytes, maxBytes) { return bytes > maxBytes ? 'over' : 'ok'; }
function deltaVerdict(delta, maxDelta) { return delta > maxDelta ? 'jump' : 'ok'; }

/**
 * حجمُ الملفّ في مرجعٍ git، أو `null` إن تعذّر (فرعٌ جديد · استنساخٌ ضحل · ملفٌّ
 * لم يكن موجوداً). 🔴 و`null` تعني **«تعذّر القياس»** لا «صفر» — والخلطُ بينهما
 * يجعل ملفّاً جديداً يبدو قفزةً بحجمه كاملاً.
 */
function sizeAtRef(ref, file) {
  try {
    var out = cp.execFileSync('git', ['show', ref + ':' + file], {
      cwd: ROOT, maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'ignore']
    });
    return out.length;
  } catch (e) { return null; }
}

/** المرجعُ الذي نقارن به: قاعدةُ الـPR إن وُجدت، وإلّا الكوميتُ السابق. */
function baseRef() {
  var envBase = process.env.GITHUB_BASE_REF;            // PR ⇒ اسمُ الفرع الهدف
  if (envBase) {
    var candidates = ['origin/' + envBase, envBase];
    for (var i = 0; i < candidates.length; i++) {
      try {
        cp.execFileSync('git', ['rev-parse', '--verify', candidates[i]],
          { cwd: ROOT, stdio: 'ignore' });
        return candidates[i];
      } catch (e) { /* التالي */ }
    }
  }
  return 'HEAD~1';
}

/**
 * 🔴 الضابطُ المعاكس — يسبق القياسَ الحقيقيّ ولا يليه.
 * فحصٌ لا يُثبت أنه **يستطيع** أن يحمرّ ليس فحصاً: لو انقلب `>` إلى `<` لمرّ كلُّ
 * شيءٍ أخضرَ أبداً **والمخرَجُ يبدو سليماً تماماً** — وهي فئةُ العطل المهيمنة هنا.
 */
function selfTest() {
  var cases = [
    { fn: 'verdict', a: 100, b: 50, want: 'over', label: 'حجمٌ فوق السقف ⇒ يحمرّ' },
    { fn: 'verdict', a: 10, b: 50, want: 'ok', label: 'حجمٌ تحت السقف ⇒ يخضرّ' },
    { fn: 'verdict', a: 50, b: 50, want: 'ok', label: 'عند السقف بالضبط ⇒ يخضرّ' },
    { fn: 'delta', a: 4000, b: 3000, want: 'jump', label: 'زيادةٌ فوق الحدّ ⇒ تحمرّ' },
    { fn: 'delta', a: 1500, b: 3000, want: 'ok', label: 'دفعةٌ معتادة ⇒ تمرّ' },
    { fn: 'delta', a: -9000, b: 3000, want: 'ok', label: 'تقليمٌ (سالب) ⇒ يمرّ دائماً' }
  ];
  var bad = cases.filter(function (c) {
    var got = c.fn === 'verdict' ? verdict(c.a, c.b) : deltaVerdict(c.a, c.b);
    c.got = got;
    return got !== c.want;
  });
  if (bad.length) {
    console.error('🔴 الضابطُ المعاكس سقط — البوّابةُ لا تقيس:');
    bad.forEach(function (c) {
      console.error('   ' + c.label + ' — توقّعتُ ' + c.want + ' وجاء ' + c.got);
    });
    process.exit(2);
  }
  console.log('✅ الضابطُ المعاكس: ٦ حالاتٍ — السقفُ والمعدّلُ يحمرّان ويخضرّان في موضعهما');
}

function main() {
  selfTest();

  var ref = baseRef();
  var failed = 0;

  console.log('');
  console.log('ميزانيّةُ الوثائق المحقونة (المقارنةُ بـ' + ref + '):');

  BUDGET.forEach(function (b) {
    var p = path.join(ROOT, b.file);
    if (!fs.existsSync(p)) {
      // 🔴 غيابُ الملفّ خروجٌ أحمرُ لا تخطٍّ صامت: بوّابةٌ تقيس ملفّاً غيرَ موجودٍ
      //    تُعلن النجاحَ أبداً، وهي أسوأ من غيابها.
      console.error('🔴 ' + b.file + ' مفقود — البوّابةُ تقيس فراغاً');
      failed++;
      return;
    }

    var bytes = fs.statSync(p).size;
    var before = sizeAtRef(ref, b.file);
    var line = '  ' + b.file + '  ' + bytes + ' بايت';

    // ① الحارسُ العامل: الزيادةُ في هذه الدفعة
    if (before === null) {
      // 🔴 «تعذّر القياس» تُقال ولا تُقرأ سلامةً — لكنّها لا تُفشل البناء:
      //    الفرعُ الجديدُ والاستنساخُ الضحل حالتان مشروعتان.
      console.log(line + '  ·  ⚠️ تعذّر قياسُ الزيادة (لا نسخةَ في ' + ref + ')');
    } else {
      var delta = bytes - before;
      var dv = deltaVerdict(delta, b.maxDelta);
      console.log(line + '  ·  ' + (delta >= 0 ? '+' : '') + delta +
        ' عن ' + ref + '  ' + (dv === 'ok' ? '✅' : '🔴') +
        '  (حدُّ الدفعة ' + b.maxDelta + ')');
      if (dv === 'jump') {
        failed++;
        console.error('');
        console.error('::error::' + b.file + ' نما ' + delta + ' بايتاً في دفعةٍ واحدة (الحدّ ' + b.maxDelta + ').');
        console.error('السبب الذي وُضع له الحدّ: ' + b.why + '.');
        console.error('');
        console.error('ولك بابان صريحان — كلاهما مقبول، والمرفوضُ النموُّ الصامتُ وحدَه:');
        console.error('  ① انقل التفصيلَ إلى `_docs/` **بحرفه** وأبقِ هنا الحكمَ الذي');
        console.error('     يُخالَف عند نقطة القرار (نمطُ «مؤشّرٌ لا سرد» — أنقذ 31,336');
        console.error('     بايتاً في 2026-09-12).');
        console.error('  ② أو ارفع `maxDelta` في `.github/scripts/check-doc-budget.js`.');
        console.error('');
        console.error('🔴 والسببُ يُكتب في **وصف الـPR وتعليقِ السكربت** — لا في ' + b.file + '.');
        console.error('   بوّابةٌ تُعالَج بكتابةِ تبريرٍ داخل الملفّ المحروس تُنتج ما جاءت لتمنعه.');
        console.error('🔴 ولا تحذف حكماً لتقليل الحجم: هذا الملفُّ يمنع كسرَ نشرٍ حيّ.');
      }
    }

    // ② الحاجزُ الخلفيّ: لا نعود إلى ما قبل تقليم 09-12
    if (verdict(bytes, b.maxBytes) === 'over') {
      failed++;
      console.error('::error::' + b.file + ' بلغ ' + bytes +
        ' — أي ما قبل تقليم 2026-09-12 (' + b.maxBytes + '). التقليمُ صار واجباً لا خياراً.');
    }
  });

  console.log('');
  console.log('⚠️ وما لا تقيسه هذه البوّابة — وحدُّها يُعلَن ولا يُترك للقارئ:');
  NOT_COVERED.forEach(function (s) { console.log('   · ' + s); });
  console.log('   ⇒ أخضرُ هنا = «وثيقةُ هذا المستودع مضبوطة»، لا «الأساسُ المحقون مضبوط».');

  console.log('');
  console.log('RESULT: ' + (failed ? '🔴 ' + failed + ' تجاوزاً' : '✅ داخل الميزانيّة'));
  process.exit(failed ? 1 : 0);
}

main();
